const particles = [];
const rays = [];
const nodes = [];

class Particle {
  constructor(x, y, vx, vy) {
    this.x = x;
    this.y = y;
    this.vx = vx;
    this.vy = vy;
    this.life = 1;
    this.maxLife = 1;
    this.size = Math.random() * 3 + 1;
  }
  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.life -= 0.008;
    this.vy += 0.15;
  }
  draw(ctx) {
    ctx.fillStyle = PALETTE[0] + Math.floor(this.life * 255).toString(16).padStart(2, '0');
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fill();
  }
}

class Ray {
  constructor(x1, y1, x2, y2, idx) {
    this.x1 = x1;
    this.y1 = y1;
    this.x2 = x2;
    this.y2 = y2;
    this.idx = idx;
    this.pulse = 0;
  }
  update(t) {
    this.pulse = Math.sin((t + this.idx * 0.3) * 0.015) * 0.5 + 0.5;
  }
  draw(ctx) {
    ctx.strokeStyle = PALETTE[2] + Math.floor(this.pulse * 200).toString(16).padStart(2, '0');
    ctx.lineWidth = 1.5 * this.pulse;
    ctx.beginPath();
    ctx.moveTo(this.x1, this.y1);
    ctx.lineTo(this.x2, this.y2);
    ctx.stroke();
  }
}

function init() {
  const w = W();
  const h = H();
  const centerX = w / 2;
  const centerY = h / 2;

  // Сетка узлов
  for (let i = -3; i <= 3; i++) {
    for (let j = -3; j <= 3; j++) {
      const x = centerX + i * 140;
      const y = centerY + j * 140;
      if (x > -50 && x < w + 50 && y > -50 && y < h + 50) {
        nodes.push({x, y, idx: i * 10 + j});
      }
    }
  }

  // Лучи между узлами
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      const dist = Math.hypot(nodes[i].x - nodes[j].x, nodes[i].y - nodes[j].y);
      if (dist < 250) {
        rays.push(new Ray(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y, rays.length));
      }
    }
  }
}

function draw(ctx, t) {
  const w = W();
  const h = H();

  // Волны излучения из узлов
  if (t % 60 < 30) {
    const waveIdx = Math.floor(t / 60);
    const wavePhase = (t % 60) / 60;
    nodes.forEach((node, idx) => {
      const radius = wavePhase * 200;
      const alpha = (1 - wavePhase) * 0.6;
      ctx.strokeStyle = PALETTE[1] + Math.floor(alpha * 255).toString(16).padStart(2, '0');
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(node.x, node.y, radius, 0, Math.PI * 2);
      ctx.stroke();
    });
  }

  // Рисуем лучи
  rays.forEach(ray => {
    ray.update(t);
    ray.draw(ctx);
  });

  // Узлы светятся
  nodes.forEach(node => {
    const glow = Math.sin(t * 0.03 + node.idx) * 0.3 + 0.7;
    ctx.fillStyle = PALETTE[0] + Math.floor(glow * 255).toString(16).padStart(2, '0');
    ctx.beginPath();
    ctx.arc(node.x, node.y, 4 * glow, 0, Math.PI * 2);
    ctx.fill();
  });

  // Частицы
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].update();
    particles[i].draw(ctx);
    if (particles[i].life <= 0) particles.splice(i, 1);
  }

  // Генерация новых частиц из активных узлов
  if (Math.random() < 0.4) {
    const node = nodes[Math.floor(Math.random() * nodes.length)];
    const angle = Math.random() * Math.PI * 2;
    const speed = Math.random() * 1.5 + 0.5;
    particles.push(new Particle(
      node.x,
      node.y,
      Math.cos(angle) * speed,
      Math.sin(angle) * speed
    ));
  }
}

init();
let frame = 0;
const animate = () => {
  const w = W();
  const h = H();
  ctx.clearRect(0, 0, w, h);
  draw(ctx, frame);
  frame++;
  requestAnimationFrame(animate);
};
animate();
